def reverse_vowels(s):
    # Define a set of vowels for quick lookup
    vowels = set(['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'])

    # Convert the string to a list of characters, as strings are immutable
    chars = list(s)

    # Initialize a pointer for the start of the string
    i = 0

    # Reverse the order of the vowels in the string
    for j in range(len(s)):
        if s[j] in vowels:
            i += 1
            while i < len(s):
                if s[i] in vowels:
                    i += 1
                else:
                    break
            else:
                chars[i-1], chars[j-1] = chars[j-1], chars[i-1]
                i += 1
    for j in range(i, len(s)):
        if s[j] in vowels:
            i += 1
            while i < len(s):
                if s[i] in vowels:
                    i += 1
                else:
                    break
            else:
                chars[i-1], chars[j-1] = chars[j-1], chars[i-1]
                i += 1
                break

    # Convert the list back to a string
    return "".join(chars)
